import{_ as s,o as n,c as i,ag as e}from"./chunks/framework.DUTPmUpA.js";const b=JSON.parse('{"title":"Подсказки о продолжительности способностей","description":"","frontmatter":{"title":"Подсказки о продолжительности способностей","author":"Noya","steamId":"76561198046984233","date":"15.12.2014"},"headers":[],"relativePath":"abilities/abilityduration-tooltips.md","filePath":"abilities/abilityduration-tooltips.md"}'),t={name:"abilities/abilityduration-tooltips.md"};function p(l,a,o,r,u,c){return n(),i("div",null,[...a[0]||(a[0]=[e(`<p>должительности способностей</p><p>**TL;DR:**abilityDuration — довольно бесполезное значение ключа, потому что тот, кто его кодировал, забыл сделать автоматическую всплывающую подсказку, как в случае с <code>AbilityDamage</code>. Используйте «duration»abilityValue и вместо этого соедините его с lua.</p><p>Представьте, что вы хотите, чтобы способность применяла модификатор на несколько секунд, длительность которого меняется с уровнем.</p><p>Вы можете попасться в ловушку и сделать это:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;AbilityDuration&quot; &quot;3 2 2&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Затем ваш модификатор ссылается на %AbilityDuration в ключе-модификаторе «Продолжительность». Пока все в порядке.</p><p>Но если вы хотите указать, что ваша способность действует в течение указанного периода времени, параметр «AbilityDuration» не генерирует всплывающую подсказку <strong>&quot;DURATION:&quot;</strong> сама по себе, поэтому у вас есть 3 варианта:</p><p><strong>Вариант 1.</strong> Напишите «Последние 3 секунды на уровне 1, а затем 2 на уровнях 2 и 3» в <code>_Description</code>.</p><p>Это плохо по причинам, объясненным ранее.</p><p><strong>Вариант 2*.</strong> В дополнение к <code>AbilityDuration</code> укажите «duration»abilityValue и синхронизируйте оба значения. Неоптимальное, но достойное решение, поскольку оно позволяет использовать способность:GetAbilityDuration(), которая принимает значение изabilityDuration.</p><p><strong>Вариант 3.</strong> Удалите «AbilityDuration», оставив только «AbilityValue». Лучший способ, насколько я могу судить.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;AbilityValues&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;duration&quot; &quot;3 2 2&quot;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>А затем, если необходимо, сделайте это в сценарии Lua.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span>function HowToTooltip(event)</span></span>
<span class="line"><span>   local ability = event.ability</span></span>
<span class="line"><span>   local duration = ability:GetLevelSpecialValueFor(&quot;duration&quot;, (ability:GetLevel() - 1))</span></span>
<span class="line"><span>   local damage = ability:GetAbilityDamage()</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Имеет одинаковые результаты и работает для любого сценария.</p>`,15)])])}const m=s(t,[["render",p]]);export{b as __pageData,m as default};
